function status(text,error=false){for(const id of ['coordStatus','coordDrawerStatus']){const el=q(id);if(el){el.textContent=text;el.classList.toggle('error',error)}}}
async function raw(path,body,token,method){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const r=await fetch(URL+path,{method:method||(body?'POST':'GET'),headers:{apikey:KEY,...(token?{Authorization:'Bearer '+token}:{}),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,signal:controller.signal});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.msg||data.error_description||data.message||'No se pudo completar la operación.');return data}finally{clearTimeout(timer)}}
async function token(){if(!session)throw new Error('Inicia sesión.');if(session.expires_at<Date.now()+60000){if(!refreshPromise)refreshPromise=raw('/auth/v1/token?grant_type=refresh_token',{refresh_token:session.refresh_token}).then(s=>{if(!session)throw new Error('Sesión cerrada.');session={...s,expires_at:Date.now()+s.expires_in*1000};return session.access_token}).finally(()=>refreshPromise=null);return refreshPromise}return session.access_token}
async function api(path,body){return raw('/rest/v1/'+path,body,await token())}
