async function authenticate(form,signup){signup=signup||signupMode;const data=new FormData(form),email=data.get('email').trim(),password=data.get('password');status(signup?'Creando cuenta…':'Comprobando acceso…');if(signup){const full_name=String(data.get('full_name')||'').trim(),phone=String(data.get('phone')||'').trim();if(full_name.length<2||phone.replace(/\D/g,'').length<7||phone.replace(/\D/g,'').length>15)throw new Error('Indica tu nombre completo y un teléfono válido.');await raw('/auth/v1/signup?redirect_to='+encodeURIComponent('https://jesusdeharotobar-gif.github.io/UMEC-gestion/'),{email,password,data:{full_name,phone}});status('Revisa tu correo y confirma tu cuenta. Al confirmarlo, UMEC recibirá tu solicitud con tus datos.');form.elements.password.value='';return}const s=await raw('/auth/v1/token?grant_type=password',{email,password});session={...s,expires_at:Date.now()+s.expires_in*1000};epoch++;await command('claim_admin');await loadMembership();if(admin){await command('enable_self',{});workspace=desktop()?'home':'personal'}else workspace='personal';await refresh()}
async function loadMembership(){members=await rows('company_members','&user_id=eq.'+encodeURIComponent(session.user.id)+'&active=eq.true');const companies=await rows('companies','&status=eq.active');members=members.filter(m=>companies.some(c=>c.id===m.company_id));if(!members.length){company=null;admin=false;render();return}if(!company||!members.some(m=>m.company_id===company))company=members[0].company_id;admin=['owner','admin'].includes(members.find(m=>m.company_id===company)?.role)}
async function refresh(){if(!session||loading)return;loading=true;const current=epoch;try{await loadMembership();const requests=await rows('coord_join_requests','&order=created_at.desc,id.desc');if(current!==epoch)return;joinRequests=company?requests.filter(r=>r.company_id===company):requests;if(!company){lastAt=new Date().toLocaleTimeString('es-ES');render();return true}const base='&company_id=eq.'+encodeURIComponent(company);const result=await Promise.all([rows('coord_workers',base+'&order=name.asc'),rows('coord_services',base+'&order=starts_at.asc,id.asc'),rows('coord_availability',base+'&order=starts_at.asc,id.asc'),admin?api('coord_events?select=*&company_id=eq.'+encodeURIComponent(company)+'&order=id.desc&limit=80'):[]]);if(current!==epoch)return;[workers,services,blocks,events]=result;lastAt=new Date().toLocaleTimeString('es-ES');dirtyForm=false;drawerDirty=false;await syncOwnProfile();await syncApprovedEmployees();await syncManagementAvailability();await importNativeServices();await reconcile();render();return true}catch(err){status('Conexión interrumpida. '+err.message,true);return false}finally{loading=false}}
