function availabilityBeforePlanning(personal=false){const eligible=workers.filter(w=>w.active&&(!personal||w.user_id===session?.user.id));return '<section class="coord-card coord-availability"><h2>Disponibilidad</h2><p class="coord-muted">Disponible salvo bloqueos y servicios confirmados o propuestos. Un bloqueo que coincide con un servicio activo requiere reasignarlo primero.</p>'+(eligible.length?'<form id="coordAvailability"><label class="coord-field">Trabajador<select name="employee_id">'+options(eligible.map(w=>[w.employee_id,w.name]),'')+'</select></label><div class="coord-two"><label class="coord-field">Desde<input type="datetime-local" name="starts_at" required></label><label class="coord-field">Hasta<input type="datetime-local" name="ends_at" required></label></div><label class="coord-field">Motivo (opcional)<input name="reason" maxlength="300"></label><button class="coord-btn" type="submit">Bloquear horario</button></form>':'<p>Aún no hay una ficha de trabajador vinculada.</p>')+blocks.filter(b=>new Date(b.ends_at)>new Date()&&(!personal||eligible.some(w=>w.employee_id===b.employee_id))).map(b=>'<div class="coord-worker"><b>'+e(workers.find(w=>w.employee_id===b.employee_id)?.name)+'</b><span>'+e(pretty(b.starts_at))+' — '+e(pretty(b.ends_at))+'</span><p>'+e(b.reason)+'</p><button class="coord-btn" data-action="unblock" data-id="'+e(b.id)+'">Retirar bloqueo</button></div>').join('')+'</section>'}
function publishPanel(){const d=vault();if(!d)return '<section class="coord-card"><h2>Enviar servicios desde Gestión</h2><p>Abre Gestión con tu contraseña y vuelve a coordinación para publicar los servicios existentes.</p><button class="coord-btn primary" data-action="workspace" data-workspace="management">Abrir Gestión</button></section>';const candidates=d.servicios.filter(s=>s.estado==='Pendiente');return '<section class="coord-card"><h2>Enviar desde Gestión</h2><p class="coord-muted">Se comparte nombre, teléfono, dirección, horario y las instrucciones que indiques aquí. No se comparten tarifas, cobros ni notas privadas del cliente.</p><form id="coordPublish"><label class="coord-field">Servicio<select name="id" required><option value="">Selecciona un servicio</option>'+candidates.map(s=>'<option value="'+e(s.id)+'">'+e(s.fecha+' '+s.hora+' · '+(d.clientes.find(c=>c.id===s.cliente)?.nombre||'Cliente')+(services.some(c=>c.id===s.id)?' · Publicado':''))+'</option>').join('')+'</select></label><label class="coord-field">Instrucciones para el trabajador<textarea name="instructions" maxlength="4000" placeholder="Solo la información necesaria para prestar el servicio"></textarea></label><p id="coordPreview" class="coord-muted"></p><button class="coord-btn primary" type="submit">Enviar a Coordinación / actualizar</button></form><p class="coord-muted">Las asignaciones y bloqueos de coordinación se gestionan aquí. Los bloqueos antiguos de Gestión se pueden incorporar con el botón siguiente.</p><button class="coord-btn" data-action="import-blocks">Incorporar bloqueos de Gestión</button></section>'}
