const agendaBlockedBeforeReset=agendaBlocked;
agendaBlocked=function(date){if(agendaBlockedBeforeReset(date))return true;const own=ownWorkers()[0];if(!own)return false;const start=new Date(date+'T00:00:00'),end=new Date(start);end.setDate(end.getDate()+1);return blocks.some(b=>b.employee_id===own.employee_id&&new Date(b.starts_at)<=start&&new Date(b.ends_at)>=end)};
// A personal removal of a Gestión-managed block must also clear its source,
