const commandBeforeAvailabilitySync=command;
command=async function(operation,payload={}){const b=operation==='remove_availability'?blocks.find(b=>b.id===payload.id&&b.employee_id===payload.employee_id&&b.reason?.startsWith('[Gestión] ')):null;const result=await commandBeforeAvailabilitySync(operation,payload);if(b&&vault()){const d=vault(),own=ownWorkers()[0],records=[...(d.disponibilidadEmpleados||[]).filter(r=>r.empleado===b.employee_id),...(own?.employee_id===b.employee_id?(d.disponibilidad||[]):[])];let changed=false;for(const r of records){const start=new Date(r.fecha+'T00:00:00'),end=new Date(start);end.setDate(end.getDate()+1);if(r.bloqueado&&+start===+new Date(b.starts_at)&&+end===+new Date(b.ends_at)){r.bloqueado=false;changed=true}const previous=r.franjas||[];r.franjas=previous.filter(f=>+new Date(r.fecha+'T'+f.inicio)!==+new Date(b.starts_at)||+new Date(r.fecha+'T'+f.fin)!==+new Date(b.ends_at));if(r.franjas.length!==previous.length)changed=true}if(changed&&!await persist())throw Error('Bloqueo retirado en Coordinación. Falta guardar su cambio en Gestión: vuelve a actualizar.')}return result};

async function importBlocksBeforeReset(){const d=vault();if(!d)throw new Error('Abre Gestión primero.');let count=0;for(const r of d.disponibilidadEmpleados||[]){if(!workers.some(w=>w.employee_id===r.empleado&&w.active))continue;const slots=r.bloqueado?[{inicio:'00:00',fin:'00:00',next:true,motivo:r.motivo}]:(r.franjas||[]);for(const slot of slots){const start=new Date(r.fecha+'T'+slot.inicio),end=new Date(r.fecha+'T'+slot.fin);if(slot.next)end.setDate(end.getDate()+1);if(end<=new Date()||blocks.some(b=>b.employee_id===r.empleado&&new Date(b.starts_at).getTime()===start.getTime()&&new Date(b.ends_at).getTime()===end.getTime()))continue;await command('availability',{employee_id:r.empleado,starts_at:start.toISOString(),ends_at:end.toISOString(),reason:slot.motivo||'Bloqueo incorporado de Gestión'});count++}}return count+' bloqueo(s) incorporado(s).'}
