function billingChoice(mode='puntual'){if(!vault())throw new Error('Abre Gestión para consultar tus tarifas y guardar el cobro.');const r=currentRates(),pack=String(mode).startsWith('pack-'),hours=pack?Number(mode.slice(5)):1;if(mode!=='puntual'&&![3,6,9,12].includes(hours))throw new Error('Elige una contratación válida.');const amount=Number(pack?r.packs[hours]:r.hour);if(!Number.isFinite(amount)||amount<0)throw new Error('Revisa las tarifas de Gestión.');return {mode,hours,amount,pack,rates:{...r,packs:{...r.packs}}}}
