async function prepareBilling(form){const d=vault();if(!d)throw new Error('Desbloquea Gestión antes de crear el servicio con su cobro.');const f=Object.fromEntries(new FormData(form)),choice=billingChoice(f.billing_mode),request=createDraft.request_id||(createDraft.request_id=crypto.randomUUID()),id='coord-billing-'+company+'-'+request,old=(d.configuracion||[]).find(x=>x.id===id);if(old){if(old.mode!==choice.mode||old.clientRef!==(f.client_ref||'')||old.paid!==(f.billing_status==='paid')||old.method!==(f.billing_method||''))throw new Error('Hay un envío pendiente de confirmar. Conserva la contratación original y vuelve a guardar.');return old}if(f.billing_status==='paid'&&!f.billing_method)throw new Error('Indica cómo se ha recibido el pago.');const intent={id,request,company,mode:choice.mode,hours:choice.hours,amount:choice.amount,pack:choice.pack,rates:choice.rates,clientRef:f.client_ref||'',paid:f.billing_status==='paid',method:f.billing_method||'',date:day()};const previous=d.configuracion||[];d.configuracion=[...previous,intent];try{if(!await persist())throw new Error('No se pudo guardar la contratación. El servicio no se ha enviado.')}catch(err){d.configuracion=previous;throw err}return intent}
