function slotWorkers(date){if(!vault()||!/^\d{4}-\d{2}-\d{2}$/.test(date||'')||!/^\d{2}:\d{2}$/.test(createDraft.time||'09:00'))return [];const s=bookingCandidate(date);return teamRoster().filter(w=>w.linked&&w.active).map(w=>({...w,conflict:slotConflict(w,s)}))}
function monthGrid(month,cell){const first=new Date(month.getFullYear(),month.getMonth(),1),offset=(first.getDay()+6)%7;return '<div class="plan-week">'+['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(x=>'<span>'+x+'</span>').join('')+'</div><div class="plan-days">'+Array.from({length:42},(_,i)=>{const date=new Date(first);date.setDate(1-offset+i);return cell(date,dateKey(date),date.getMonth()!==month.getMonth())}).join('')+'</div>'}
function monthHead(month,kind){return '<div class="plan-month-head"><button type="button" class="coord-iconbtn" data-action="plan-month" data-kind="'+kind+'" data-delta="-1" aria-label="Mes anterior">‹</button><b>'+e(month.toLocaleDateString('es-ES',{month:'long',year:'numeric'}))+'</b><button type="button" class="coord-iconbtn" data-action="plan-month" data-kind="'+kind+'" data-delta="1" aria-label="Mes siguiente">›</button></div>'}
function bookingPlanner(){if(!vault())return '';const date=createDraft.date||filters.date||day(),picked=createDraft.employee_id||'',roster=slotWorkers(date),selected=roster.find(w=>w.employee_id===picked),punctual=sundayPunctual(date,createDraft.billing_mode||'puntual');return '<section class="plan-booking"><h3>Disponibilidad del equipo</h3><p>Colores calculados para las '+e(createDraft.time||'09:00')+' y '+billingChoice(createDraft.billing_mode||'puntual').hours+' h de duración. '+(picked?'Trabajador: '+e(selected?.name||'Seleccionado')+'.':'Se muestra cuántas personas pueden cubrir todo el servicio.')+'</p>'+monthHead(bookingMonth,'booking')+monthGrid(bookingMonth,(d,key,out)=>{const workers=slotWorkers(key),available=workers.filter(w=>!w.conflict),one=workers.find(w=>w.employee_id===picked),forbidden=sundayPunctual(key,createDraft.billing_mode||'puntual'),free=picked?one&&!one.conflict:available.length>0,label=forbidden?'Sin puntual 1 h':!workers.length?'Sin equipo':picked?(free?'Disponible':'No disponible'):available.length+' disponibles';return '<button type="button" class="plan-day '+(out?'plan-out ':'')+(forbidden?'plan-forbidden':free?'plan-free':'plan-busy')+'" data-action="plan-date" data-date="'+key+'" aria-pressed="'+(key===date)+'" '+(forbidden?'disabled':'')+' aria-label="'+e(key+' · '+label)+'"><b>'+d.getDate()+'</b><small>'+e(label)+'</small></button>'})+'<p class="plan-legend">Verde: cabe el horario completo · Rojo: sin disponibilidad · Gris: puntual de 1 h no permitido el domingo.</p><div class="plan-slot-result" role="status">'+(punctual?'<b>Los domingos no se admite servicio puntual de 1 hora. Elige un pack u otro día.</b>':'<b>'+e(date)+' · '+e(createDraft.time||'09:00')+'</b>')+roster.map(w=>'<div><span>'+e(w.name)+'</span><b class="'+(w.conflict?'plan-text-busy':'plan-text-free')+'">'+e(w.conflict||'Disponible para todo el servicio')+'</b></div>').join('')+(!roster.length?'<p>No hay trabajadores activos con cuenta vinculada.</p>':'')+'</div></section>'}
function updateBookingPanel(){const box=root.querySelector('#planBooking');if(box)box.innerHTML=bookingPlanner();const select=root.querySelector('#coordCreate [name=employee_id]');if(select&&vault()){const roster=slotWorkers(createDraft.date||filters.date||day());for(const opt of select.options){if(!opt.value)continue;const w=roster.find(w=>w.employee_id===opt.value);opt.disabled=!w||!!w.conflict;opt.textContent=w?w.name+(w.conflict?' · '+w.conflict:' · Disponible'):opt.textContent}const w=roster.find(w=>w.employee_id===select.value);select.setCustomValidity(select.value&&(!w||w.conflict)?w?.conflict||'Cuenta no disponible':'')}}
function createDialog(){let html=createDialogBeforePlanning();html=html.replace(/<label class="coord-field">Seleccionar un cliente de Gestión \(opcional\)<select name="client_ref">[\s\S]*?<\/select><\/label>/,'');html=html.replace('<div class="coord-formsection"><h3>01','<input type="hidden" name="client_ref" value="'+e(createDraft.client_ref||'')+'"><div class="coord-formsection"><h3>01');html=html.replace('<label class="coord-field">Tipo de servicio *','<div id="planClientResults" class="plan-client-results" aria-live="polite">'+clientResults()+'</div><label class="coord-field">Tipo de servicio *');html=html.replace('name="client_name"','name="client_name" autocomplete="off" aria-describedby="planClientResults"');html=html.replace('autocomplete="name"','');html=html.replace(/<input name="date" type="date" required value="([^\"]*)">/,'<input name="date" type="date" required value="$1" aria-describedby="planBooking">');html=html.replace('<label class="coord-field">Forma de contratación *','<div id="planBooking">'+bookingPlanner()+'</div><label class="coord-field">Forma de contratación *');return html}
function availability(personal=false){let html=availabilityBeforeWorkerCalendar(personal);if(!personal)return html;html=html.replace('<h2>Mi disponibilidad</h2>','<h1 class="worker-calendar-title">Mi calendario</h1>').replace('Selecciona un día para marcarlo como no disponible. Los bloqueos se comparten con Coordinación. Un día con citas debe reasignarse antes de bloquearlo.','Toca un día para ver tus servicios o marcarlo como no disponible. Tus cambios se comparten con Coordinación.');html=html.replace(/(<button[^>]*data-action="plan-availability-day"[^>]*data-date="([^"]+)"[^>]*>[\s\S]*?)(<\/button>)/g,(all,content,date,close)=>{const jobs=ordered(myServices().filter(s=>s.status!=='cancelled'&&onDate(s,date)));if(!jobs.length)return all;const preview=jobs.slice(0,2).map(s=>'<span class="worker-cell-job '+e(s.status)+'" title="'+e(timeLabel(s)+' · '+s.client_name+' · '+labels[s.status])+'"><b>'+e(local(s.starts_at).slice(11,16))+'</b><span>'+e(s.client_name||s.title)+'</span></span>').join('');return content+'<span class="worker-cell-jobs">'+preview+(jobs.length>2?'<small>+'+(jobs.length-2)+' más</small>':'')+'</span>'+close});return html}

function availabilityBeforeWorkerCalendar(personal=false){const eligible=workers.filter(w=>w.active&&(!personal||w.user_id===session?.user.id));if(!eligible.length)return availabilityBeforePlanning(personal);if(!eligible.some(w=>w.employee_id===availabilityWorker))availabilityWorker=eligible[0].employee_id;const picked=availabilityWorker,start=new Date(availabilityDay+'T00:00:00'),end=new Date(start);end.setDate(end.getDate()+1);const dayBlocks=blocks.filter(b=>b.employee_id===picked&&new Date(b.starts_at)<end&&start<new Date(b.ends_at)),jobs=services.filter(s=>s.employee_id===picked&&['offered','assigned','in_progress','incident'].includes(s.status)&&new Date(s.starts_at)<end&&start<new Date(s.ends_at));return '<section class="coord-card plan-availability">'+(planFeedback?'<div class="coord-status '+(planFeedbackError?'error':'')+'" role="status">'+e(planFeedback)+'</div>':'')+'<h2>'+(personal?'Mi disponibilidad':'Calendario de disponibilidad')+'</h2><p>Selecciona un día para marcarlo como no disponible. Los bloqueos se comparten con Coordinación. Un día con citas debe reasignarse antes de bloquearlo.</p>'+(eligible.length>1?'<label class="coord-field">Trabajador<select id="planAvailabilityWorker">'+options(eligible.map(w=>[w.employee_id,w.name]),picked)+'</select></label>':'<b>'+e(eligible[0].name)+'</b>')+monthHead(availabilityMonth,'availability')+monthGrid(availabilityMonth,(d,key,out)=>{const a=new Date(key+'T00:00:00'),b=new Date(a);b.setDate(b.getDate()+1);const bs=blocks.filter(x=>x.employee_id===picked&&new Date(x.starts_at)<b&&a<new Date(x.ends_at)),full=bs.some(x=>new Date(x.starts_at)<=a&&new Date(x.ends_at)>=b),count=services.filter(s=>s.employee_id===picked&&['offered','assigned','in_progress','incident'].includes(s.status)&&new Date(s.starts_at)<b&&a<new Date(s.ends_at)).length;return '<button type="button" class="plan-day '+(out?'plan-out ':'')+(full?'plan-busy':bs.length?'plan-partial':count?'plan-booked':'plan-free')+'" data-action="plan-availability-day" data-date="'+key+'" aria-pressed="'+(key===availabilityDay)+'"><b>'+d.getDate()+'</b><small>'+(full?'No disponible':bs.length?'Bloqueo parcial':count?count+' cita(s)':'Sin reservas')+'</small></button>'})+'<p class="plan-legend">Verde: sin reservas · Azul: con citas · Amarillo: bloqueo parcial · Rojo: día bloqueado.</p><div class="plan-slot-result"><h3>'+e(availabilityDay)+'</h3>'+jobs.map(s=>'<p>'+e(timeLabel(s)+' · '+(s.client_name||s.title))+'</p>').join('')+dayBlocks.map(b=>'<p>'+e(pretty(b.starts_at)+' — '+pretty(b.ends_at))+'<br>'+e(b.reason||'No disponible')+' <button type="button" class="coord-textbutton" data-action="plan-remove-block" data-id="'+e(b.id)+'">Retirar este bloqueo</button></p>').join('')+(!dayBlocks.length&&!jobs.length?'<p>Día sin reservas ni bloqueos.</p>':'')+'<button type="button" class="coord-btn" data-action="plan-block-day" '+(jobs.length||dayBlocks.some(b=>new Date(b.starts_at)<=start&&new Date(b.ends_at)>=end)?'disabled':'')+'>Marcar todo el día no disponible</button></div><details class="plan-hour-details"><summary>Bloquear solo unas horas / consultar todos los bloqueos</summary>'+availabilityBeforePlanning(personal)+'</details></section>'}
root.addEventListener('input',event=>{const t=event.target;if(t.form?.id!=='coordCreate'||!['client_name','phone'].includes(t.name))return;createDraft[t.name]=t.value;createDraft.client_ref='';t.form.elements.client_ref.value='';root.querySelector('#planClientResults').innerHTML=clientResults()});
root.addEventListener('change',event=>{const t=event.target;if(t.id==='planAvailabilityWorker'){availabilityWorker=t.value;render();return}if(t.form?.id==='coordCreate'&&['date','time','employee_id','billing_mode'].includes(t.name)){createDraft[t.name]=t.value;if(t.name==='date'&&t.value)bookingMonth=new Date(t.value+'T12:00:00');updateBookingPanel()}});
root.addEventListener('click',async event=>{const b=event.target.closest('[data-action^="plan-"]');if(!b)return;event.preventDefault();event.stopImmediatePropagation();if(busy)return;const a=b.dataset.action;if(a==='plan-month'){const delta=Number(b.dataset.delta);if(b.dataset.kind==='booking'){bookingMonth=new Date(bookingMonth.getFullYear(),bookingMonth.getMonth()+delta,1);updateBookingPanel()}else{availabilityMonth=new Date(availabilityMonth.getFullYear(),availabilityMonth.getMonth()+delta,1);render()}return}if(a==='plan-date'){createDraft.date=b.dataset.date;root.querySelector('#coordCreate [name=date]').value=createDraft.date;updateBookingPanel();return}if(a==='plan-availability-day'){availabilityDay=b.dataset.date;render();root.querySelector('.plan-slot-result')?.scrollIntoView({behavior:'smooth',block:'start'});return}if(a==='plan-client'){const c=vault()?.clientes.find(c=>c.id===b.dataset.client);if(!c)return;Object.assign(createDraft,{client_ref:c.id,client_name:c.nombre,phone:c.telefono||'',address:addressOf(c)});render();updateBookingPanel();return}if(a==='plan-new-client'){const d=vault(),form=root.querySelector('#coordCreate'),f=Object.fromEntries(new FormData(form));if(!d)return;if(!f.client_name?.trim()||normalPhone(f.phone).length<7){createError='Indica el nombre y un teléfono válido antes de guardar la ficha.';render();return}const duplicate=d.clientes.find(c=>normalText(c.nombre)===normalText(f.client_name)||normalPhone(c.telefono)===normalPhone(f.phone));if(duplicate){createError='Ya existe una ficha con ese nombre o teléfono. Selecciónala en los resultados.';render();return}busy=true;const prior=d.clientes;try{const c={id:crypto.randomUUID(),nombre:f.client_name.trim(),telefono:f.phone.trim(),direccion:f.address?.trim()||'',notas:''};d.clientes=[...prior,c];if(!await persist())throw Error('No se pudo guardar la ficha.');Object.assign(createDraft,f,{client_ref:c.id});createError=''}catch(err){d.clientes=prior;createError=err.message}finally{busy=false;render();updateBookingPanel()}return}if(!session)return;const w=workers.find(w=>w.employee_id===availabilityWorker&&w.active&&(admin||w.user_id===session.user.id));if(!w)return;busy=true;root.querySelectorAll('button').forEach(x=>x.disabled=true);try{if(a==='plan-block-day'){const start=new Date(availabilityDay+'T00:00:00'),end=new Date(start);end.setDate(end.getDate()+1);await command('availability',{employee_id:w.employee_id,starts_at:start.toISOString(),ends_at:end.toISOString(),reason:'Día no disponible'})}if(a==='plan-remove-block'){const block=blocks.find(x=>x.id===b.dataset.id&&x.employee_id===w.employee_id);if(!block)return;if(!confirm('¿Retirar el bloqueo completo del '+pretty(block.starts_at)+' al '+pretty(block.ends_at)+'?'))return;await command('remove_availability',{employee_id:w.employee_id,id:block.id})}await refresh();planFeedback='Disponibilidad actualizada y compartida con Coordinación.';planFeedbackError=false;}catch(err){planFeedback=err.message;planFeedbackError=true;}finally{busy=false;render()}} ,true);

function createDialogBeforePlanning(){const d=createDraft;const date=d.date||filters.date||day();const clients=vault()?.clientes||[];return '<div class="coord-dialogback"><section class="coord-dialog" role="dialog" aria-modal="true" aria-labelledby="coordCreateTitle"><div class="coord-dialoghead"><div><span class="coord-eyebrow">NUEVO SERVICIO</span><h2 id="coordCreateTitle">Organiza el próximo servicio</h2></div><button type="button" class="coord-iconbtn" data-action="close-create" aria-label="Cerrar formulario">×</button></div><form id="coordCreate"><div class="coord-dialogbody"><p class="coord-muted">El servicio se guarda en coordinación y se comparte con el trabajador que elijas.</p><div id="coordCreateError" class="coord-status error" role="alert"'+(!createError?' hidden':'')+'>'+e(createError)+'</div>'+(clients.length?'<label class="coord-field">Seleccionar un cliente de Gestión (opcional)<select name="client_ref"><option value="">Introducir datos del cliente</option>'+options(clients.map(c=>[c.id,c.nombre]),d.client_ref||'')+'</select></label>':'')+'<div class="coord-formsection"><h3>01 <span>Cliente y servicio</span></h3><div class="coord-two"><label class="coord-field">Nombre del cliente *<input name="client_name" maxlength="200" required value="'+e(d.client_name)+'" autocomplete="name"></label><label class="coord-field">Teléfono de contacto<input name="phone" maxlength="80" type="tel" value="'+e(d.phone)+'" autocomplete="tel"></label></div><label class="coord-field">Tipo de servicio *<input name="title" maxlength="200" required value="'+e(d.title)+'" placeholder="Acompañamiento, atención en domicilio, recados…" list="coordTypes"></label><datalist id="coordTypes"><option value="Acompañamiento"><option value="Atención en domicilio"><option value="Acompañamiento médico"><option value="Recados y gestiones"></datalist><label class="coord-field">Dirección<input name="address" maxlength="1000" value="'+e(d.address)+'" autocomplete="street-address" placeholder="Calle, número, localidad y detalles de acceso"></label></div><div class="coord-formsection"><h3>02 <span>Fecha y horario</span></h3><div class="coord-three"><label class="coord-field">Día *<input name="date" type="date" required value="'+e(date)+'"></label><label class="coord-field">Inicio *<input name="time" type="time" required value="'+e(d.time||'09:00')+'"></label><div class="coord-field"><span>Duración contratada</span><b class="billing-hours">'+(vault()?billingChoice(d.billing_mode||'puntual').hours+' h':'Desbloquea Gestión')+'</b></div></div>'+billingFields()+'</div><div class="coord-formsection"><h3>03 <span>Asignación e instrucciones</span></h3><div class="coord-two"><label class="coord-field">Trabajador<select name="employee_id">'+workerChoices(d.employee_id||'','Asignar más adelante')+'</select></label><label class="coord-field">Modalidad<select name="mode">'+options([['direct','Asignación directa'],['acceptance','Solicitar aceptación']],d.mode||'direct')+'</select></label></div><label class="coord-field">Instrucciones para el trabajador<textarea name="instructions" maxlength="4000" placeholder="Solo la información necesaria para prestar el servicio">'+e(d.instructions)+'</textarea></label>'+workerHelp()+'<p class="coord-muted">Se comprobarán los solapamientos antes de asignar. El importe se guardará automáticamente en Cobros de Gestión.</p></div></div><div class="coord-dialogfoot"><button type="button" class="coord-btn" data-action="close-create">Cancelar</button><button type="submit" class="coord-btn primary">Crear y guardar servicio</button></div></form></section></div>'}
function renderDashboardOld(){if(!session||!company||!admin||!desktop()){renderLegacy();return}root.innerHTML=header()+dashboard()+(createOpen?createDialog():selectedServiceId?serviceSheet():'');root.querySelectorAll('button').forEach(b=>b.disabled=busy)}
async function createService(form){if(!admin||!desktop())throw new Error('Solo administradores en ordenador.');const data=Object.fromEntries(new FormData(form));const selectedClient=vault()?.clientes.find(c=>c.id===data.client_ref);if(!selectedClient||normalText(selectedClient.nombre)!==normalText(data.client_name)||normalPhone(selectedClient.telefono)!==normalPhone(data.phone))throw new Error('Busca y selecciona una ficha de cliente. Si no existe, guarda su ficha primero.');if(sundayPunctual(data.date,data.billing_mode))throw new Error('Los domingos no se admite servicio puntual de 1 hora. Elige un pack u otro día.');const hours=billingChoice(data.billing_mode).hours,start=new Date(data.date+'T'+data.time),end=new Date(start.getTime()+hours*3600000);if(!data.client_name?.trim()||!data.title?.trim())throw new Error('Indica el cliente y el tipo de servicio.');if(!Number.isFinite(start.getTime())||!(hours>=.5&&hours<=24&&Number.isInteger(hours*2)))throw new Error('Revisa la fecha y la duración (de 0,5 a 24 horas).');const payload={request_id:createDraft.request_id||(createDraft.request_id=crypto.randomUUID()),client_name:data.client_name.trim(),title:data.title.trim(),phone:(data.phone||'').trim(),address:(data.address||'').trim(),instructions:data.instructions||'',starts_at:start.toISOString(),ends_at:end.toISOString(),employee_id:data.employee_id||'',mode:data.mode||'direct'};const chosen=teamRoster().find(w=>w.employee_id===payload.employee_id);const remoteConflict=payload.employee_id?(!chosen?'Trabajador no disponible':slotConflict(chosen,payload)):'';if(remoteConflict)throw new Error(remoteConflict);const conflict=legacyConflict(payload.employee_id,payload);if(conflict)throw new Error(conflict);if(payload.employee_id&&vault())await importBlocks();await prepareBilling(form);const result=await command('create',payload);if(!result.id)throw new Error('No se recibió la confirmación del servicio. Actualiza la agenda antes de repetir.');if(!services.some(s=>s.id===result.id))services.push(result);await importPricedServices();return {result,date:local(result.starts_at).slice(0,10),clientRef:data.client_ref}}
async function importNativeServices(){
 await importPricedServices();
 const d=vault();if(!admin||!d)return;
 const pending=services.filter(s=>s.id.startsWith('COORD-')&&!d.servicios.some(x=>x.id===s.id));if(!pending.length)return;
 const rates=typeof currentRates==='function'?currentRates():null;
 if(!rates||!Number.isFinite(Number(rates.hour)))throw new Error('No se pudieron consultar las tarifas de Gestión.');
 const previousClients=d.clientes,previousServices=d.servicios;d.clientes=[...d.clientes];d.servicios=[...d.servicios];
 try{for(const s of pending){let c=d.clientes.find(c=>c.nombre===s.client_name&&(c.telefono||'')===s.phone);if(!c){c={id:'CL-'+s.id,nombre:s.client_name,telefono:s.phone,direccion:s.address,notas:''};d.clientes.push(c)}
 const hours=(new Date(s.ends_at)-new Date(s.starts_at))/3600000;
 d.servicios.push({id:s.id,cliente:c.id,empleado:s.employee_id||'',fecha:local(s.starts_at).slice(0,10),hora:local(s.starts_at).slice(11,16),tipo:s.title,modo:'puntual',bono:null,horas:hours,direccion:s.address,notas:s.instructions,estado:s.status==='cancelled'?'Cancelado':'Pendiente',excesoMin:0,extra:0,precio:Math.round(rates.hour*hours*100)/100,tarifaHora:rates.hour,tarifaExtra:rates.hourExtra,tarifaCortesia:rates.grace,coord:{company,status:s.status,version:s.version}})}
 if(!await persist())throw new Error('Servicio guardado en coordinación. No cierres Gestión: falta guardar su copia local.');
 }catch(err){d.clientes=previousClients;d.servicios=previousServices;if(typeof renderAll==='function')renderAll();throw err}
}
// One personal sign-in. Authoritative permissions remain independent of the selected view.
let workspace='home',personalFilters={date:'',state:'active'};
function ownWorkers(){return workers.filter(w=>w.user_id===session?.user.id&&w.active)}
function myServices(){const ids=new Set(ownWorkers().map(w=>w.employee_id));return services.filter(s=>ids.has(s.employee_id))}
function header(){const title=!session?'Acceso personal':admin?({home:'Mi espacio',personal:'Mis servicios',coordination:'Centro de Coordinación',management:'Gestión',requests:'Solicitudes'}[workspace]||'Mi espacio'):'Mis servicios';const links=(admin?joinBadge()+'<button class="coord-btn" data-action="workspace" data-workspace="home">Mi espacio</button><button class="coord-btn" data-action="workspace" data-workspace="personal">Mis servicios</button>':'')+'<button class="coord-btn" data-action="refresh">Actualizar</button><button class="coord-btn" data-action="logout">Cerrar sesión</button>';return '<header class="coord-bar compact-bar"><div class="compact-identity"><b>UMEC · '+title+'</b><small>'+(session?e(session.user.email):'Cada persona entra con su propia cuenta')+'</small></div>'+(session?'<details class="compact-menu"'+(desktop()?' open':'')+'><summary aria-label="Abrir menú de cuenta">Menú'+(admin&&pendingJoins().length?' <span class="compact-count">'+pendingJoins().length+'</span>':'')+'</summary><div class="coord-actions">'+links+'</div></details>':'')+'</header>'+(session&&admin&&workspace==='coordination'?'<nav class="compact-areas" aria-label="Áreas de trabajo"><button class="coord-btn" data-action="workspace" data-workspace="management">Gestión de avisos</button><span aria-current="page">Coordinación</span></nav>':'')}
function login(){root.innerHTML=header()+'<div class="coord-access"><section class="coord-welcome"><img src="umec-logo.svg" alt="UMEC"><span class="coord-eyebrow">UNA MANO EN CASA</span><h1>Tu trabajo. <br>Todo en un mismo lugar.</h1><p>Servicios, equipo y coordinación, conectados.</p><div class="coord-accessbenefit"><b>Para el equipo</b><span>Consulta tus servicios y comunica su progreso.</span></div><div class="coord-accessbenefit"><b>Para ti, como administrador</b><span>Coordina al equipo y realiza tus propios servicios con la misma cuenta.</span></div></section><section class="coord-signin"><span class="coord-eyebrow">ACCESO A UMEC</span><h2>Bienvenido de nuevo</h2><p>Entra con tu correo y tu contraseña personal.</p><div id="coordStatus" class="coord-status" role="status" aria-live="polite">Tus permisos se reconocen automáticamente al entrar.</div><form id="coordLogin"><div id="coordSignupFields" hidden><label class="coord-field">Nombre y apellidos<input name="full_name" maxlength="160" autocomplete="name" placeholder="Tu nombre completo"></label><label class="coord-field">Teléfono<input name="phone" type="tel" maxlength="40" autocomplete="tel" placeholder="Tu teléfono de contacto"></label></div><label class="coord-field">Correo electrónico<input name="email" type="email" autocomplete="username" required placeholder="nombre@correo.com"></label><label class="coord-field">Contraseña de tu cuenta<input name="password" type="password" autocomplete="current-password" minlength="8" required placeholder="Tu contraseña personal"></label><button class="coord-btn primary coord-signinbutton" type="submit">Entrar a mi espacio</button><div class="coord-register"><span>¿Es tu primera vez?</span><button class="coord-btn" type="button" name="signup" data-action="auth-signup-mode">Crear mi cuenta</button></div></form><button id="coordBackToLogin" hidden type="button" class="coord-textbutton" data-action="auth-login-mode">Ya tengo cuenta · Volver a entrar</button><p class="coord-accessnote">Al confirmar el correo, enviaremos tus datos al administrador para que acepte tu incorporación.</p><details class="coord-accessfaq"><summary>¿Qué contraseña debo utilizar?</summary><p>Usa la contraseña que elegiste al crear tu cuenta con correo. La contraseña antigua de Gestión solo se solicita al administrador cuando abre sus datos guardados.</p></details></section></div>'}
async function syncOwnProfile(){const d=vault(),own=ownWorkers()[0];if(!admin||!d||!own||(d.empleados||[]).some(w=>w.id===own.employee_id))return;const previous=d.empleados;d.empleados=[...(previous||[]),{id:own.employee_id,nombre:own.name,email:session.user.email,whatsapp:'',puesto:'Administrador · servicios',direccion:'',notas:''}];try{if(!await persist())throw new Error('Falta guardar tu perfil de servicios en Gestión. Actualiza sin cerrar la app.')}catch(err){d.empleados=previous;throw err}}
function renderHome(){const own=ownWorkers()[0],count=myServices().filter(s=>!['completed','cancelled'].includes(s.status)).length;root.innerHTML=header()+'<div class="coord-home"><span class="coord-eyebrow">TU CUENTA UMEC</span><h1>Elige dónde quieres trabajar</h1><p>Tu cuenta de administrador también sirve para realizar servicios. Cambia de espacio sin cerrar sesión.</p><div id="coordStatus" class="coord-status" role="status" aria-live="polite">'+(own?'Tu perfil de servicios está activo. Ya puedes asignarte servicios desde Coordinación.':'Comprobando tu perfil de servicios…')+'</div>'+joinBanner()+'<div class="coord-homecards"><button class="coord-homecard" data-action="workspace" data-workspace="personal"><span class="coord-homeicon">◷</span><h2>Mis servicios</h2><p>Tu agenda personal, propuestas y servicios que vas a realizar.</p><small>'+count+' servicio(s) activo(s)</small><strong>Ver mi agenda →</strong></button><button class="coord-homecard" data-action="workspace" data-workspace="coordination"><span class="coord-homeicon">▦</span><h2>Coordinación</h2><p>Crea servicios, organiza horarios y asigna al equipo o a ti mismo.</p><small>'+(desktop()?'Disponible en este ordenador':'Disponible desde el ordenador')+'</small><strong>'+(desktop()?'Abrir coordinación →':'Abrir en ordenador')+'</strong></button><button class="coord-homecard" data-action="workspace" data-workspace="management"><span class="coord-homeicon">▤</span><h2>Gestión</h2><p>Clientes, tarifas, packs, cobros y copias de seguridad.</p><small>'+(vault()?'Tus datos ya están desbloqueados':'Requiere desbloquear tus datos guardados')+'</small><strong>Abrir Gestión →</strong></button></div><p class="coord-muted">Una cuenta personal para entrar. La clave de protección de Gestión conserva tus datos anteriores.</p></div>'}
function renderPersonal(){const own=ownWorkers(),items=myServices().filter(s=>onDate(s,availabilityDay)&&s.status!=='cancelled');root.innerHTML=header()+'<main class="coord-personal worker-calendar-main"><div id="coordStatus" class="coord-status" role="status" aria-live="polite">'+(lastAt?'Actualizado a las '+e(lastAt):'Conectando…')+'</div>'+(!own.length?workerJoinState():availability(true)+'<section class="personal-day-services"><h2>Servicios del '+e(new Date(availabilityDay+'T12:00:00').toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long'}))+'</h2><p>Toca un día del calendario para consultar sus servicios. Aquí puedes aceptar propuestas y comunicar el inicio o final.</p>'+(items.length?items.map(s=>card(s,true)).join(''):'<div class="coord-empty"><h2>Sin servicios para este día</h2><p>No tienes servicios asignados en la fecha seleccionada.</p></div>')+'</section>')+'</main>';root.querySelectorAll('button').forEach(b=>b.disabled=busy)}
function render(){if(!session){login();return}if(!company){renderPersonal();return}if(!admin){workspace='personal';renderPersonal();return}if(workspace==='requests'){renderJoinInbox();return}if(workspace==='personal'){renderPersonal();return}if(workspace==='coordination'&&desktop()){root.innerHTML=header()+dashboard()+(createOpen?createDialog():selectedServiceId?serviceSheet():'');root.querySelectorAll('button').forEach(b=>b.disabled=busy);return}if(workspace==='coordination'&&!desktop())workspace='home';renderHome()}
async function openManagement(){if(!session||!admin){status('Gestión está reservada a la cuenta del administrador.',true);return}await token();await loadMembership();if(!admin){render();return}workspace='management';createOpen=false;if(vault()){root.hidden=true;return}showAuth(authMode||'login');root.hidden=true;document.getElementById('authPassword')?.focus()}
// Registration data is a request only: membership is granted solely by an administrator.
let joinRequests=[],signupMode=false;
function workerContact(w){const r=joinRequests.find(r=>r.company_id===company&&r.status==='approved'&&r.employee_id===w.employee_id);return r?'<small class="coord-workercontact">'+e(r.email)+' · '+e(r.phone)+'</small>':''}
function pendingJoins(){return joinRequests.filter(r=>r.company_id===company&&r.status==='pending')}
function ownJoin(){return joinRequests.find(r=>r.user_id===session?.user.id)}
function validJoin(r){return r&&r.full_name?.trim().length>=2&&(r.phone||'').replace(/\D/g,'').length>=7&&(r.phone||'').replace(/\D/g,'').length<=15}
function joinBadge(){return admin?'<button class="coord-btn coord-joinbadge" data-action="join-inbox">Solicitudes'+(pendingJoins().length?' <span>'+pendingJoins().length+'</span>':'')+'</button>':''}
function joinBanner(){const count=pendingJoins().length;return count?'<div class="coord-joinbanner"><div><b>'+count+(count===1?' trabajador solicita':' trabajadores solicitan')+' acceso a UMEC</b><span>Sus datos y correo ya están aquí. Revisa y acepta su incorporación.</span></div><button class="coord-btn primary" data-action="join-inbox">Revisar solicitudes</button></div>':''}
function joinPanel(){const pending=pendingJoins();return '<section class="coord-card coord-joinpanel"><div class="coord-sectionhead"><div><span class="coord-eyebrow">INCORPORACIÓN DEL EQUIPO</span><h2>Solicitudes de trabajadores</h2></div><span class="coord-pill">'+pending.length+' pendiente(s)</span></div><p class="coord-muted">El trabajador introduce sus datos y confirma su correo. Tú solo revisas y aceptas: su ficha se crea y vincula automáticamente.</p>'+(pending.length?pending.map(r=>{const existing=vault()?.empleados?.find(w=>(w.email||'').trim().toLowerCase()===r.email.toLowerCase());return '<article class="coord-joinrequest"><div class="coord-itemhead"><div><h3>'+e(r.full_name)+'</h3><span class="coord-pill completed">Correo confirmado</span></div><time class="coord-muted">'+e(pretty(r.created_at))+'</time></div><dl><div><dt>Correo</dt><dd>'+e(r.email)+'</dd></div><div><dt>Teléfono</dt><dd>'+e(r.phone||'Pendiente de completar')+'</dd></div></dl>'+(validJoin(r)?'<p class="coord-muted">'+(existing?'Se vinculará con la ficha de '+e(existing.nombre)+'.':'Se creará su ficha automáticamente al aceptar.')+'</p>':'<p class="coord-joinincomplete">Faltan datos. El trabajador debe abrir la app y completar su nombre y teléfono.</p>')+'<details><summary class="coord-muted">Vincular con una ficha existente (opcional)</summary><label class="coord-field">Ficha<select data-join-employee="'+e(r.id)+'">'+options([['','Crear ficha automáticamente'],...(vault()?.empleados||[]).map(w=>[w.id,w.nombre])],existing?.id||'')+'</select></label></details><div class="coord-actions"><button class="coord-btn primary" data-action="approve-join" data-id="'+e(r.id)+'" '+(!validJoin(r)?'disabled':'')+'>Aceptar trabajador</button><button class="coord-btn danger" data-action="reject-join" data-id="'+e(r.id)+'">No aceptar</button></div></article>'}).join(''):'<div class="coord-empty">No hay solicitudes pendientes. Las nuevas confirmaciones aparecerán aquí automáticamente.</div>')+'<div class="coord-mailprepared"><b>Aviso dentro de la app: activo</b><p>Se actualiza cada 15 segundos mientras tienes la app abierta. Las solicitudes se guardan aunque la tengas cerrada.</p><b>Correo automático: preparado, pendiente de activar</b><p>El envío externo requiere conectar el servicio de correo. Todavía no se están enviando avisos por correo ni WhatsApp.</p></div></section>'}
function coordReturnButton(){return '<button class="coord-textbutton coord-return" data-action="workspace" data-workspace="'+(desktop()?'coordination':'home')+'">← '+(desktop()?'Volver a Coordinación':'Volver a mi espacio')+'</button>'}
function renderJoinInbox(){root.innerHTML=header()+'<main class="coord-personal coord-joininbox">'+coordReturnButton()+'<span class="coord-eyebrow">ADMINISTRACIÓN DEL EQUIPO</span><h1>Solicitudes del equipo</h1><div id="coordStatus" class="coord-status" role="status" aria-live="polite">Revisa quién solicita incorporarse a UMEC.</div>'+joinPanel()+'</main>';root.querySelectorAll('button:not([data-action="approve-join"])').forEach(b=>b.disabled=busy);root.querySelectorAll('[data-action="approve-join"]').forEach(b=>b.disabled=busy||!validJoin(joinRequests.find(r=>r.id===b.dataset.id)))}
function rejectedJoinForm(r){return '<section class="coord-card coord-joinprofile"><h2>Volver a solicitar acceso</h2><p class="coord-muted">Puedes usar tu misma cuenta. Completa o corrige tus datos y envía una nueva solicitud al administrador.</p>'+(r.reason?'<p class="coord-joinincomplete">Motivo anterior: '+e(r.reason)+'</p>':'')+'<form id="coordJoinProfile"><label class="coord-field">Nombre y apellidos<input name="full_name" required maxlength="160" autocomplete="name" value="'+e(r.full_name||'')+'"></label><label class="coord-field">Teléfono<input name="phone" type="tel" required maxlength="40" autocomplete="tel" value="'+e(r.phone||'')+'"></label><p class="coord-muted">Tu correo sigue confirmado: '+e(session.user.email)+'</p><button class="coord-btn primary" type="submit">Volver a solicitar acceso</button></form></section>'}
function workerJoinState(){const r=ownJoin();if(r?.status==='rejected')return rejectedJoinForm(r);if(r?.status==='approved')return '<div class="coord-empty"><h2>Tu acceso necesita revisión</h2><p>Tu solicitud ya fue aceptada. Si no ves tu agenda, pulsa Actualizar o contacta con UMEC.</p><button class="coord-btn" data-action="refresh">Actualizar mi acceso</button></div>';if(validJoin(r))return '<div class="coord-joinwaiting"><span class="coord-homeicon">✓</span><h2>Tu solicitud ya está enviada</h2><p>El administrador de UMEC recibirá el aviso en su app. Cuando te acepte, tu agenda se activará automáticamente.</p><p><b>'+e(r.full_name)+'</b><br>'+e(r.email)+'<br>'+e(r.phone)+'</p><button class="coord-btn primary" data-action="refresh">Comprobar mi acceso</button></div>';return '<section class="coord-card coord-joinprofile"><h2>Completa tu ficha para solicitar acceso</h2><p class="coord-muted">No tienes que comunicar tu correo al administrador. Al enviar estos datos le aparecerá tu solicitud automáticamente.</p><form id="coordJoinProfile"><label class="coord-field">Nombre y apellidos<input name="full_name" required maxlength="160" autocomplete="name" value="'+e(r?.full_name||session.user.user_metadata?.full_name||'')+'"></label><label class="coord-field">Teléfono<input name="phone" type="tel" required maxlength="40" autocomplete="tel" value="'+e(r?.phone||session.user.user_metadata?.phone||'')+'"></label><p class="coord-muted">Correo confirmado: '+e(session.user.email)+'</p><button class="coord-btn primary" type="submit">Enviar mi solicitud a UMEC</button></form></section>'}
function setSignupMode(value){signupMode=value;const form=q('coordLogin');if(!form)return;const fields=q('coordSignupFields');fields.hidden=!value;for(const name of ['full_name','phone'])form.elements[name].required=value;const primary=form.querySelector('.coord-signinbutton');primary.hidden=value;const submit=form.querySelector('[name="signup"]');submit.textContent=value?'Crear cuenta y enviar confirmación':'Crear mi cuenta';const back=q('coordBackToLogin');back.hidden=!value;const heading=root.querySelector('.coord-signin h2');if(heading)heading.textContent=value?'Crea tu cuenta de trabajador':'Bienvenido de nuevo';status(value?'Rellena tus datos. Al confirmar el correo, UMEC recibirá tu solicitud.':'Tus permisos se reconocen automáticamente al entrar.');if(value)form.elements.full_name.focus()}
async function syncApprovedEmployees(){const d=vault();if(!admin||!d)return;const approved=joinRequests.filter(r=>r.company_id===company&&r.status==='approved'&&r.employee_id);if(!approved.length)return;const previous=d.empleados||[];let changed=false;const next=previous.map(w=>({...w}));for(const r of approved){const index=next.findIndex(w=>w.id===r.employee_id);if(index>=0&&next[index].joinRequestId===r.id)continue;const record={...(index>=0?next[index]:{puesto:'Trabajador',direccion:'',notas:''}),id:r.employee_id,nombre:r.full_name,email:r.email,whatsapp:r.phone,joinRequestId:r.id};if(index>=0)next[index]=record;else next.push(record);changed=true}if(changed){d.empleados=next;try{if(!await persist())throw new Error('El trabajador está aceptado. Falta guardar su ficha en Gestión: actualiza sin cerrar la app.')}catch(err){d.empleados=previous;throw err}}}
// Coordination views share one service sheet and the existing server-checked mutations.
let serviceQuery='',selectedServiceId='',drawerDirty=false,listDate='';
const workerName=s=>workers.find(w=>w.employee_id===s.employee_id)?.name||'Sin trabajador';
const timeLabel=s=>local(s.starts_at).slice(11,16)+'–'+local(s.ends_at).slice(11,16);
const pill=s=>'<span class="coord-pill '+e(s.status)+'">'+e(labels[s.status]||s.status)+'</span>';
const isActive=s=>!['completed','cancelled'].includes(s.status);
function matchesQuery(s){return !serviceQuery||[s.client_name,s.title,s.address,workerName(s)].join(' ').toLocaleLowerCase('es').includes(serviceQuery.toLocaleLowerCase('es'))}
function ordered(items){return items.slice().sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at)||String(a.id).localeCompare(String(b.id)))}
function serviceRow(s){const hints={unassigned:'Elige quién realizará el servicio',offered:'El trabajador debe aceptar o rechazar',assigned:'Confirmado · pendiente de comenzar',in_progress:'El trabajador ha comunicado el inicio',incident:'Revisa y resuelve el aviso del trabajador',completed:'Finalizado · revisa el cierre en Gestión',cancelled:'Cancelado · se conserva en el historial'};return '<button class="coord-service-row guided-row" data-action="open-service" data-id="'+e(s.id)+'"><span class="coord-row-time"><small>FECHA Y HORARIO</small><b>'+e(new Date(s.starts_at).toLocaleDateString('es-ES',{day:'numeric',month:'short',year:'numeric'}))+'</b><small>'+e(timeLabel(s))+'</small></span><span class="coord-row-client"><small>CLIENTE · SERVICIO</small><b>'+e(s.client_name||'Cliente sin nombre')+'</b><small>'+e(s.title)+'</small>'+(s.address?'<small class="guided-address">'+e(s.address)+'</small>':'')+'</span><span class="coord-row-worker"><small>TRABAJADOR</small><b>'+e(workerName(s))+'</b></span><span class="guided-state">'+pill(s)+'<small>'+e(hints[s.status]||'Consulta la ficha del servicio')+'</small></span><span class="guided-open">Abrir ficha →</span></button>'}

function emptyPanel(title,detail,action=''){return '<div class="coord-empty coord-clear-empty"><span aria-hidden="true">✓</span><h3>'+e(title)+'</h3><p>'+e(detail)+'</p>'+action+'</div>'}
function panel(title,subtitle,content,action=''){return '<section class="coord-clear-panel"><div class="coord-clear-panelhead"><div><h2>'+e(title)+'</h2>'+(subtitle?'<p>'+e(subtitle)+'</p>':'')+'</div>'+action+'</div>'+content+'</section>'}
function overview(){const today=ordered(services.filter(s=>onDate(s,day())&&isActive(s))),attention=services.filter(s=>['unassigned','incident'].includes(s.status)).sort((a,b)=>(a.status==='incident'?0:1)-(b.status==='incident'?0:1)||new Date(a.starts_at)-new Date(b.starts_at)),upcoming=ordered(services.filter(s=>isActive(s)&&new Date(s.ends_at)>new Date())).slice(0,5);return '<div class="coord-summary-grid">'+panel('Necesita tu atención','Pendientes e incidencias de todo el calendario',attention.length?attention.slice(0,5).map(serviceRow).join(''):emptyPanel('Todo al día','No quedan servicios sin asignar ni incidencias abiertas.'),'<button class="coord-btn" data-action="quick-filter" data-state="unassigned" data-scope="global">Ver pendientes</button>')+panel('Hoy, de un vistazo',new Date().toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long'}),today.length?today.map(serviceRow).join(''):emptyPanel('No hay servicios activos hoy','Puedes crear uno o consultar otra fecha.'),'<button class="coord-btn" data-action="go-calendar">Abrir calendario</button>')+'</div><div class="coord-summary-bottom">'+panel('Próximos servicios','Los siguientes servicios activos',upcoming.length?upcoming.map(serviceRow).join(''):emptyPanel('Agenda despejada','Los nuevos servicios aparecerán aquí.'))+panel('Cómo coordinar un servicio','Tres pasos sencillos','<ol class="coord-howto"><li><b>Crea el servicio</b><span>Indica cliente, lugar y horario.</span></li><li><b>Elige quién lo realiza</b><span>Comprueba disponibilidad y asigna directamente o pide aceptación.</span></li><li><b>Sigue su progreso</b><span>El trabajador comunica el inicio, final y cualquier incidencia.</span></li></ol>')+'</div>'}
function sharedFilters(includeDate=false){return '<div class="coord-clear-filters"><label class="coord-searchlabel"><span>Buscar servicio</span><input id="coordServiceSearch" type="search" value="'+e(serviceQuery)+'" placeholder="Cliente, dirección o trabajador…" autocomplete="off"></label>'+(includeDate?'<label>Fecha (opcional)<input id="coordListDate" type="date" value="'+e(listDate)+'"></label>':'')+'<label>Estado<select id="coordState">'+options([['active','Servicios activos'],['all','Todos los estados'],...Object.entries(labels)],filters.state)+'</select></label><label>Trabajador<select id="coordWorkerFilter">'+options([['','Todo el equipo'],...workers.map(w=>[w.employee_id,w.name+(w.user_id===session?.user.id?' (yo)':'')])],filters.worker)+'</select></label><button class="coord-btn" data-action="clear-filters">Limpiar filtros</button></div>'}
function serviceList(){const items=ordered(filteredCalendarServices().filter(s=>matchesQuery(s)&&(!listDate||onDate(s,listDate))));const tabs=[['active','Activos'],['unassigned','Por asignar'],['offered','Esperando respuesta'],['in_progress','En curso'],['incident','Incidencias'],['all','Todos']];return sharedFilters(true)+'<p class="guided-scope">'+(listDate?'Fecha: '+e(new Date(listDate+'T12:00:00').toLocaleDateString('es-ES')):'Todas las fechas')+' · '+e(filters.state==='active'?'Activos: pendientes, propuestos, asignados, en curso e incidencias':filters.state==='all'?'Incluye finalizados y cancelados':labels[filters.state])+' · '+e(filters.worker?workers.find(w=>w.employee_id===filters.worker)?.name||'Trabajador seleccionado':'Todo el equipo')+'</p><div class="coord-listchips">'+tabs.map(([id,name])=>'<button class="'+(filters.state===id?'active':'')+'" data-action="quick-filter" data-state="'+id+'">'+name+'</button>').join('')+'</div>'+panel('Servicios',''+items.length+' resultado(s) · abre un servicio para asignar o consultar su estado',items.length?items.map(serviceRow).join(''):emptyPanel('No hay coincidencias','Prueba otra búsqueda o limpia los filtros.','<button class="coord-btn" data-action="clear-filters">Mostrar servicios activos</button>'))}
function dailyAgenda(){const date=filters.date||day(),items=ordered(filteredCalendarServices().filter(s=>onDate(s,date)));return '<section class="coord-daily"><div class="coord-dailyhead"><span class="coord-eyebrow">DÍA SELECCIONADO</span><h2>'+e(new Date(date+'T12:00:00').toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long'}))+'</h2><span class="coord-muted">'+items.length+' servicio(s) · pulsa uno para abrir su ficha</span></div><div class="coord-dailylist">'+(items.length?items.map(serviceRow).join(''):emptyPanel('Día sin servicios','No hay servicios para estos filtros.'))+'</div><button class="coord-dailyadd" data-action="new-service">＋ Crear servicio para este día</button></section>'}
function slotConflict(w,s){if(!w.active)return 'Acceso desactivado';if(!w.linked)return 'Falta aceptar o vincular';const blocked=blocks.some(b=>b.employee_id===w.employee_id&&new Date(b.starts_at)<new Date(s.ends_at)&&new Date(s.starts_at)<new Date(b.ends_at));if(blocked)return 'Horario bloqueado';const occupied=services.some(x=>x.id!==s.id&&x.employee_id===w.employee_id&&['offered','assigned','in_progress','incident'].includes(x.status)&&new Date(x.starts_at)<new Date(s.ends_at)&&new Date(s.starts_at)<new Date(x.ends_at));if(occupied)return 'Ocupado en ese horario';return legacyConflict(w.employee_id,s)||''}
function assignmentChoices(s,value){return '<option value="">Sin asignar · decidir más adelante</option>'+teamRoster().map(w=>{const conflict=slotConflict(w,s);return '<option value="'+e(w.employee_id)+'"'+(value===w.employee_id?' selected':'')+(conflict?' disabled':'')+'>'+e(w.name+' · '+(conflict||'Disponible'))+'</option>'}).join('')}
function assignment(s){const available=teamRoster().filter(w=>!slotConflict(w,s)).length;return '<section class="coord-sheet-assignment"><h3>¿Quién realizará el servicio?</h3><p class="coord-muted">'+available+' trabajador(es) disponible(s) para este horario. Las propuestas pendientes también reservan su horario.</p><label class="coord-field">Trabajador<select data-worker="'+e(s.id)+'">'+assignmentChoices(s,s.employee_id||'')+'</select></label><label class="coord-field">Cómo quieres asignarlo<select data-mode="'+e(s.id)+'">'+options([['direct','Asignar directamente'],['acceptance','Pedir al trabajador que acepte']],s.mode)+'</select></label><p class="coord-muted">Directa: aparece confirmado en su agenda. Con aceptación: debe aceptar antes de iniciar.</p>'+workerHelp()+'</section>'}
function progress(s){const steps=s.mode==='acceptance'?['unassigned','offered','assigned','in_progress','completed']:['unassigned','assigned','in_progress','completed'];const position=steps.indexOf(s.status==='incident'?s.previous_status:s.status);return '<ol class="coord-progress" aria-label="Progreso del servicio">'+steps.map((key,i)=>'<li class="'+(i<position?'done':i===position?'current':'')+'"><span>'+(i<position?'✓':i+1)+'</span><small>'+e(({unassigned:'Por asignar',offered:'Propuesta',assigned:'Asignado',in_progress:'En curso',completed:'Finalizado'})[key])+'</small></li>').join('')+'</ol>'}
function card(s,personal=false){if(!admin||personal)return cardBase(s,personal);const phone=(s.phone||'').replace(/[^+\d]/g,'');return '<article class="coord-sheet-card"><div class="coord-sheet-summary">'+pill(s)+'<h2>'+e(s.client_name||'Servicio')+'</h2><p>'+e(s.title)+'</p></div>'+progress(s)+'<div class="coord-sheet-facts"><div><small>Fecha y horario</small><b>'+e(pretty(s.starts_at))+' — '+e(pretty(s.ends_at))+'</b></div><div><small>Trabajador</small><b>'+e(workerName(s))+'</b></div><div><small>Lugar del servicio</small><b>'+e(s.address||'Sin dirección indicada')+'</b></div><div><small>Instrucciones</small><p>'+e(s.instructions||'Sin instrucciones adicionales')+'</p></div></div><div class="coord-actions">'+(phone?'<a class="coord-btn" href="tel:'+e(phone)+'">Llamar al contacto</a>':'')+(s.address?'<a class="coord-btn" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(s.address)+'">Abrir ubicación</a>':'')+'</div>'+(s.status==='incident'?'<section class="coord-sheet-warning"><h3>Hay una incidencia abierta</h3><p>'+e(events.find(ev=>ev.service_id===s.id&&ev.action==='incident')?.detail||'Revisa el aviso y resuélvelo para continuar con el servicio.')+'</p>'+button('resolve','Marcar incidencia resuelta',s,'primary')+'</section>':'')+(['unassigned','offered','assigned'].includes(s.status)?assignment(s):'')+(s.status==='completed'?'<div class="coord-sheet-success"><b>Servicio finalizado por el trabajador</b><p>Revisa los minutos adicionales y cierra el cobro desde Gestión.</p></div>':'')+'<details class="coord-sheet-more"><summary>Más opciones del servicio</summary>'+(s.status==='unassigned'?reschedule(s):'<p class="coord-muted">Para cambiar el horario, el servicio debe estar sin asignar. Los servicios iniciados conservan su historial.</p>')+(!['completed','cancelled'].includes(s.status)?button('cancel','Cancelar este servicio',s,'danger'):'')+'</details></article>'}
function serviceSheet(){const s=services.find(s=>s.id===selectedServiceId);if(!s)return '';return '<div class="coord-serviceback"><section class="coord-servicesheet" role="dialog" aria-modal="true" aria-labelledby="coordServiceTitle"><header class="coord-sheet-head"><div><span class="coord-eyebrow">COORDINACIÓN</span><h2 id="coordServiceTitle">Ficha del servicio</h2></div><button class="coord-iconbtn" data-action="close-service" aria-label="Cerrar ficha">×</button></header><div class="coord-sheet-body"><div id="coordDrawerStatus" class="coord-status" role="status" aria-live="polite">Consulta los datos y coordina el siguiente paso.</div>'+card(s)+'</div>'+(['unassigned','offered','assigned'].includes(s.status)?'<footer class="coord-sheet-footer"><span id="coordAssignmentNotice">La disponibilidad se comprueba al guardar.</span><button class="coord-btn primary" data-action="assign" data-id="'+e(s.id)+'">Guardar asignación</button></footer>':'')+'</section></div>'}
function teamTimeline(){const date=filters.date||day(),start=new Date(date+'T00:00:00'),end=new Date(start);end.setDate(end.getDate()+1);const duration=end-start;const jobs=filteredCalendarServices().filter(s=>onDate(s,date));const roster=[...(!filters.worker?[{employee_id:'',name:'Sin asignar'}]:[]),...teamRoster().filter(w=>w.linked&&(!filters.worker||w.employee_id===filters.worker))];const hours=Array.from({length:24},(_,i)=>String(i).padStart(2,'0')+':00');return '<section class="coord-calendar coord-timeline"><div class="coord-calhead"><div><span class="coord-eyebrow">AGENDA POR TRABAJADOR</span><h2>'+e(new Date(date+'T12:00:00').toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long'}))+'</h2></div><div class="coord-actions"><button class="coord-iconbtn" data-action="previous" aria-label="Día anterior">‹</button><button class="coord-btn" data-action="today">Hoy</button><button class="coord-iconbtn" data-action="next" aria-label="Día siguiente">›</button></div></div><p class="coord-timelinehelp">Desliza la agenda horizontalmente para consultar las 24 horas. Pulsa un servicio para abrirlo.</p><div class="coord-timeline-scroll"><div class="coord-timeline-hours"><span>Trabajador</span><div>'+hours.map(h=>'<small>'+h+'</small>').join('')+'</div></div>'+roster.map(w=>{const own=ordered(jobs.filter(s=>(s.employee_id||'')===w.employee_id)),lanes=[];const placed=own.map(s=>{let lane=lanes.findIndex(last=>last<=new Date(s.starts_at));if(lane<0)lane=lanes.length;lanes[lane]=new Date(s.ends_at);return {s,lane}});const count=Math.max(1,lanes.length);return '<div class="coord-timeline-row"><b>'+e(w.name)+'</b><div class="coord-timeline-track" style="height:'+Math.max(64,count*49+12)+'px">'+blocks.filter(b=>b.employee_id===w.employee_id&&onDate(b,date)).map(b=>{const left=Math.max(0,(new Date(b.starts_at)-start)/duration*100),right=Math.min(100,(new Date(b.ends_at)-start)/duration*100);return '<span class="coord-timeline-block" style="left:'+left+'%;width:'+(right-left)+'%" title="Horario no disponible">No disponible</span>'}).join('')+placed.map(({s,lane})=>{const left=Math.max(0,(new Date(s.starts_at)-start)/duration*100),right=Math.min(100,(new Date(s.ends_at)-start)/duration*100);return '<button class="coord-timeline-job '+e(s.status)+'" style="left:'+left+'%;width:'+(right-left)+'%;top:'+(6+lane*49)+'px" data-action="open-service" data-id="'+e(s.id)+'" title="'+e(s.client_name+' · '+timeLabel(s)+' · '+labels[s.status])+'"><b>'+e(s.client_name||s.title)+'</b><small>'+e(timeLabel(s))+'</small></button>'}).join('')+'</div></div>'}).join('')+'</div></section>'}
function calendar(){return calendarView==='day'?teamTimeline():calendarBase()}
function teamView(){const date=filters.date||day();return '<div class="coord-team-intro"><p>Disponibilidad para <b>'+e(new Date(date+'T12:00:00').toLocaleDateString('es-ES',{day:'numeric',month:'long'}))+'</b>. Consulta sus reservas y bloqueos registrados.</p><label class="coord-teamdate">Consultar fecha<input id="coordTeamDate" type="date" value="'+e(date)+'"></label><button class="coord-btn" data-action="join-inbox">Solicitudes del equipo'+(pendingJoins().length?' · '+pendingJoins().length:'')+'</button></div><div class="coord-team-cards">'+teamRoster().map(w=>{const count=services.filter(s=>s.employee_id===w.employee_id&&isActive(s)&&onDate(s,date)).length,blocked=blocks.some(b=>b.employee_id===w.employee_id&&onDate(b,date));return '<article class="coord-team-person"><span class="coord-person-avatar">'+e((w.name||'?').slice(0,1))+'</span><h3>'+e(w.name)+'</h3>'+workerContact(w)+'<p>'+(!w.active?'Acceso desactivado':!w.linked?'Pendiente de aceptar o vincular':(count?count+' servicio(s) ese día':'Sin servicios ese día')+(blocked?' · Tiene horarios bloqueados':' · Sin bloqueos registrados'))+'</p><div class="coord-actions">'+(w.linked?'<button class="coord-btn" data-action="worker-agenda" data-worker-id="'+e(w.employee_id)+'">Ver su agenda</button>':'<button class="coord-btn" data-action="join-inbox">Revisar solicitudes</button>')+'</div></article>'}).join('')+'</div>'+availability()+'<details class="coord-advanced-team"><summary>Opciones avanzadas: vincular una ficha existente</summary>'+workerPanel()+'</details>'}
function notices(){const incidents=services.filter(s=>s.status==='incident');return (incidents.length?panel('Incidencias abiertas','Abre el servicio para revisar y resolver la incidencia',incidents.map(serviceRow).join('')):'')+panel('Actividad del equipo','Últimos 80 movimientos',events.length?events.map(ev=>{const s=services.find(s=>s.id===ev.service_id),actor=workers.find(w=>w.user_id===ev.actor)?.name||(ev.actor===session.user.id?'Tú':'Administración'),assigned=workers.find(w=>w.employee_id===ev.detail);const detail=assigned?'Trabajador: '+assigned.name:ev.detail===ev.service_id?'':ev.detail||'';return '<div class="coord-event"><span class="coord-eventdot"></span><div><b>'+e(actions[ev.action]||'Actualización del equipo')+'</b><p>'+e(s?(s.client_name+' · '+s.title):'Equipo UMEC')+'</p>'+(detail?'<p>'+e(detail)+'</p>':'')+'<small>'+e(actor)+'</small>'+(s?'<button class="coord-textbutton" data-action="open-service" data-id="'+e(s.id)+'">Ver servicio</button>':'')+'</div><time>'+e(pretty(ev.created_at))+'</time></div>'}).join(''):emptyPanel('Todavía no hay movimientos','Las respuestas y los cambios de estado aparecerán aquí.'))}

function sectionGuide(){const help={resumen:['Qué revisar primero','1. Revisa incidencias y servicios sin asignar. 2. Consulta las citas de hoy. 3. Abre una ficha para actuar.'],agenda:['Cómo usar el calendario','Elige Mes para localizar una fecha, Semana para planificar o Por trabajador para comparar horarios. Pulsa una cita para abrirla. Los filtros afectan al calendario y al listado del día.'],servicios:['Localiza el servicio y abre su ficha','Busca al cliente, limita la fecha si lo necesitas y elige un estado. En cada fila verás quién lo realiza, en qué punto está y qué queda por hacer.'],equipo:['Consulta antes de asignar','Elige la fecha y abre la agenda del trabajador. Tener un servicio no significa estar ocupado todo el día: revisa sus horas y los bloqueos. Las nuevas incorporaciones se aceptan en Solicitudes.'],avisos:['Distingue incidencias de historial','Las incidencias abiertas requieren tu intervención. Debajo se muestra el historial de respuestas y cambios, del más reciente al más antiguo. Abre la ficha para actuar.'],gestion:['Trae un servicio que ya existe en Gestión','1. Desbloquea Gestión si hace falta. 2. Elige un servicio pendiente. 3. Revisa las indicaciones y publica. Si ya estaba publicado, se actualizan sus datos. Después asigna el trabajador desde Servicios.']};const h=help[section];return h?'<section class="guided-help"><b>'+e(h[0])+'</b><p>'+e(h[1])+'</p></section>':''}

function dashboard(){const counts=[['unassigned','Por asignar'],['offered','Esperando respuesta'],['in_progress','En curso'],['incident','Incidencias']];const nav=[['resumen','⌂','Resumen'],['agenda','▦','Calendario'],['servicios','≡','Servicios'],['equipo','♙','Equipo'],['avisos','◉','Actividad'],['gestion','⇄','Importar de Gestión']];const titles={resumen:['Tu coordinación, bajo control.','Empieza por lo que necesita atención y continúa con la agenda de hoy.'],agenda:['Planifica con una visión completa.','Mes, semana o jornada por trabajador. Selecciona un servicio para coordinarlo.'],servicios:['Encuentra y coordina cada servicio.','Busca por cliente, dirección o trabajador y filtra por estado.'],equipo:['Cada persona, con su agenda.','Consulta reservas, bloqueos y solicitudes de incorporación.'],avisos:['Sigue lo que ocurre en el equipo.','Incidencias, respuestas y cambios explicados con nombres reconocibles.'],gestion:['Incorpora servicios que ya tenías.','Publica un servicio guardado en Gestión y continúa su coordinación aquí.']};const [title,subtitle]=titles[section]||titles.resumen;return '<div class="coord-workspace guided-section-'+e(section)+'"><nav class="coord-rail" aria-label="Secciones de coordinación"><div class="coord-railbrand"><img src="umec-logo.svg" alt="UMEC"><b>COORDINACIÓN<small>Servicios y equipo</small></b></div><p class="coord-railcaption">TU TRABAJO DIARIO</p>'+nav.map(([id,icon,name])=>'<button data-action="section" data-section="'+id+'" class="'+(section===id?'active':'')+'"><span aria-hidden="true">'+icon+'</span>'+name+'</button>').join('')+'<button data-action="join-inbox"><span aria-hidden="true">＋</span>Solicitudes'+(pendingJoins().length?' ('+pendingJoins().length+')':'')+'</button><div class="coord-railfoot">UMEC · Centro de Coordinación<small>Asigna al equipo o elige tu propio perfil para realizar un servicio.</small></div></nav><div class="coord-main"><div class="coord-hero"><div><span class="coord-eyebrow">SERVICIOS / '+e(({resumen:'RESUMEN',agenda:'CALENDARIO',servicios:'LISTADO',equipo:'EQUIPO',avisos:'ACTIVIDAD',gestion:'GESTIÓN'})[section]||'RESUMEN')+'</span><h1>'+title+'</h1><p>'+subtitle+'</p></div><button class="coord-btn primary coord-createbutton" data-action="new-service">＋ Crear servicio</button></div><div id="coordStatus" class="coord-status" role="status" aria-live="polite">'+(lastAt?'Actualizado a las '+e(lastAt):'Cargando coordinación…')+'<small>Las solicitudes y los estados se actualizan mientras la app está abierta.</small></div>'+joinBanner()+sectionGuide()+'<div class="coord-metrics">'+counts.map(([id,name])=>'<button class="coord-metric '+id+'" data-action="quick-filter" data-state="'+id+'" data-scope="global"><span>'+name+'</span><strong>'+services.filter(s=>s.status===id).length+'</strong><small>Todas las fechas · Ver servicios →</small></button>').join('')+'</div>'+(section==='resumen'?overview():section==='servicios'?serviceList():section==='agenda'?'<div class="coord-toolbar"><div class="coord-segment">'+[['month','Mes'],['week','Semana'],['day','Por trabajador']].map(([id,name])=>'<button data-action="view" data-view="'+id+'" aria-pressed="'+(calendarView===id)+'" class="'+(calendarView===id?'active':'')+'">'+name+'</button>').join('')+'</div></div>'+sharedFilters()+'<div class="coord-planning '+(calendarView==='day'?'coord-planning-day':'')+'">'+calendar()+dailyAgenda()+'</div>':section==='equipo'?teamView():section==='avisos'?notices():publishPanel())+'</div></div>'}
function closeServiceSheet(){if(drawerDirty&&!confirm('Hay cambios de asignación sin guardar. ¿Cerrar sin guardarlos?'))return;selectedServiceId='';drawerDirty=false;dirtyForm=false;render();root.querySelector('.coord-createbutton')?.focus()}
root.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(b&&!desktop())root.querySelector('.compact-menu')?.removeAttribute('open');if(!b)return;const action=b.dataset.action;if(['workspace','section','join-inbox','new-service','setup-team'].includes(action)&&selectedServiceId){if(drawerDirty&&!confirm('Hay cambios de asignación sin guardar. ¿Continuar sin guardarlos?')){event.preventDefault();event.stopImmediatePropagation();return}selectedServiceId='';drawerDirty=false;dirtyForm=false}if(['open-service','close-service','quick-filter','go-calendar','clear-filters','worker-agenda'].includes(action)){event.preventDefault();event.stopImmediatePropagation();if(busy||!admin||!desktop())return;if(action==='close-service'){closeServiceSheet();return}if(action==='open-service'){if(!services.some(s=>s.id===b.dataset.id))return;epoch++;selectedServiceId=b.dataset.id;drawerDirty=false;dirtyForm=false;render();root.querySelector('.coord-servicesheet [data-action="close-service"]')?.focus();return}selectedServiceId='';drawerDirty=false;dirtyForm=false;if(action==='quick-filter'){section='servicios';filters.state=b.dataset.state;if(b.dataset.scope==='global')filters.worker='';listDate='';serviceQuery=''}if(action==='go-calendar'){section='agenda';filters.worker='';filters.state='active';serviceQuery='';filters.date=day();calendarView='month';calendarMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1)}if(action==='clear-filters'){filters.state='active';filters.worker='';serviceQuery='';listDate=''}if(action==='worker-agenda'){section='agenda';serviceQuery='';calendarView='day';filters.worker=b.dataset.workerId;filters.date=filters.date||day();filters.state='active'}render();root.scrollTop=0;return}if(action==='refresh'&&selectedServiceId&&drawerDirty){event.preventDefault();event.stopImmediatePropagation();status('Guarda la asignación o cierra la ficha antes de actualizar.',true);return}if(['previous','next'].includes(action)&&calendarView==='day'){event.preventDefault();event.stopImmediatePropagation();if(busy)return;const d=new Date((filters.date||day())+'T12:00:00');d.setDate(d.getDate()+(action==='next'?1:-1));filters.date=dateKey(d);calendarMonth=new Date(d.getFullYear(),d.getMonth(),1);render()}});
root.addEventListener('input',event=>{if(event.target.id!=='coordServiceSearch')return;serviceQuery=event.target.value;const pos=event.target.selectionStart;render();const input=q('coordServiceSearch');if(input){input.focus();try{input.setSelectionRange(pos,pos)}catch{}}});
root.addEventListener('change',event=>{if(event.target.id==='coordListDate'){listDate=event.target.value;render()}if(event.target.id==='coordTeamDate'){filters.date=event.target.value||day();render()}if(event.target.matches('[data-worker],[data-mode]')){drawerDirty=true;const note=q('coordAssignmentNotice');if(note)note.textContent='Tienes cambios sin guardar.'}});
root.addEventListener('keydown',event=>{if(!selectedServiceId||createOpen)return;if(event.key==='Escape'){event.preventDefault();closeServiceSheet();return}if(event.key==='Tab'){const dialog=root.querySelector('.coord-servicesheet');if(!dialog)return;const all=[...dialog.querySelectorAll('button,a,input,select,textarea,summary')].filter(el=>!el.disabled&&el.getClientRects().length),first=all[0],last=all[all.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});

root.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b||!['join-inbox','approve-join','reject-join','auth-login-mode','auth-signup-mode'].includes(b.dataset.action))return;event.preventDefault();event.stopImmediatePropagation();if(busy)return;if(b.dataset.action==='auth-login-mode'){setSignupMode(false);return}if(b.dataset.action==='auth-signup-mode'){if(signupMode)q('coordLogin').requestSubmit();else setSignupMode(true);return}if(!admin||!session)return;if(b.dataset.action==='join-inbox'){workspace='requests';createOpen=false;dirtyForm=false;render();root.scrollTop=0;return}busy=true;root.querySelectorAll('button').forEach(x=>x.disabled=true);try{const r=joinRequests.find(r=>r.id===b.dataset.id);if(!r)throw new Error('Actualiza las solicitudes.');const approve=b.dataset.action==='approve-join';const payload={id:r.id};if(approve){const select=[...root.querySelectorAll('[data-join-employee]')].find(x=>x.dataset.joinEmployee===r.id);payload.employee_id=select?.value||''}else{const reason=prompt('Motivo para no aceptar la solicitud (opcional):');if(reason===null)return;payload.reason=reason}await command(approve?'approve_join':'reject_join',payload);const ok=await refresh();if(ok)status(approve?'Trabajador aceptado. Su cuenta y su ficha están vinculadas.':'Solicitud revisada.')}catch(err){status(err.message,true)}finally{busy=false;root.querySelectorAll('button').forEach(x=>x.disabled=false);root.querySelectorAll('[data-action="approve-join"]').forEach(x=>x.disabled=!validJoin(joinRequests.find(r=>r.id===x.dataset.id)))}});
root.addEventListener('submit',async event=>{if(event.target.id!=='coordJoinProfile')return;event.preventDefault();event.stopImmediatePropagation();if(busy)return;busy=true;try{const data=Object.fromEntries(new FormData(event.target));await command('request_join',data);await refresh()}catch(err){status(err.message,true)}finally{busy=false;root.querySelectorAll('button').forEach(b=>b.disabled=false);if(selectedServiceId)root.querySelector('[data-action="close-service"]')?.focus()}});
async function confirmationEntry(){const hash=new URLSearchParams((location.hash||'').slice(1));if(!hash.has('access_token'))return false;const access=hash.get('access_token'),refreshToken=hash.get('refresh_token');history.replaceState(null,'',location.pathname+location.search);status('Comprobando tu correo confirmado…');try{const user=await raw('/auth/v1/user',null,access);if(!user.id||!user.email_confirmed_at||!refreshToken)throw new Error('Vuelve a entrar con tu correo y contraseña para continuar.');session={access_token:access,refresh_token:refreshToken,expires_at:Date.now()+Math.min(Number(hash.get('expires_in'))||3600,3600)*1000,user};epoch++;await command('claim_admin');await loadMembership();if(admin){await command('enable_self',{});workspace=desktop()?'home':'personal'}else workspace='personal';await refresh();return true}catch(err){session=null;login();status('No se pudo completar el acceso desde el enlace. '+err.message);return true}}

root.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b||!['workspace','personal-all-dates'].includes(b.dataset.action))return;event.preventDefault();event.stopImmediatePropagation();if(busy||!session)return;if(b.dataset.action==='personal-all-dates'){personalFilters.date='';render();return}if(!admin)return;const target=b.dataset.workspace;if(target==='management'){try{await openManagement()}catch(err){status(err.message,true)}return}createOpen=false;dirtyForm=false;workspace=target;render();root.scrollTop=0});
root.addEventListener('change',event=>{if(event.target.id==='coordPersonalDate'){personalFilters.date=event.target.value;render()}if(event.target.id==='coordPersonalState'){personalFilters.state=event.target.value;render()}});
const legacyShowAuth=showAuth;
showAuth=function(mode){legacyShowAuth(mode);if(q('authTitle'))q('authTitle').textContent=mode==='setup'?'Proteger datos de Gestión':'Desbloquear datos de Gestión';if(q('authIntro'))q('authIntro').textContent='Solo administrador. Esta clave protege tus clientes, cobros y copias guardadas.';if(q('authSubmit'))q('authSubmit').textContent=mode==='setup'?'Proteger mis datos':'Desbloquear Gestión';if(q('authPassword'))q('authPassword').placeholder='Contraseña de protección de Gestión';if(q('forgotPasswordBtn'))q('forgotPasswordBtn').textContent='Recuperar mis datos de Gestión'};
const legacySubmitAuth=submitAuth;
submitAuth=async function(){if(!session||!admin){root.hidden=false;render();return}try{await token();await loadMembership();if(!admin){root.hidden=false;render();return}await legacySubmitAuth();if(vault()){workspace='management';root.hidden=true}}catch(err){if(q('authError'))q('authError').textContent=err.message}};

root.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(!['section','view','previous','next','today','pick-date','metric','new-service','close-create','setup-team'].includes(action))return;event.stopImmediatePropagation();event.preventDefault();if(busy)return;if(!admin||!desktop())return;
 if(action==='section'){section=b.dataset.section;dirtyForm=false}if(action==='setup-team'){createOpen=false;section='equipo';dirtyForm=false}
 if(action==='view')calendarView=b.dataset.view;
 if(action==='previous'||action==='next'){const n=action==='next'?1:-1;if(calendarView==='week'){const date=new Date((filters.date||day())+'T12:00:00');date.setDate(date.getDate()+7*n);filters.date=dateKey(date);calendarMonth=new Date(date.getFullYear(),date.getMonth(),1)}else{calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+n,1);filters.date=dateKey(calendarMonth)}}
 if(action==='today'){filters.date=day();const date=new Date();calendarMonth=new Date(date.getFullYear(),date.getMonth(),1)}
 if(action==='pick-date')filters.date=b.dataset.date;
 if(action==='metric'){section='agenda';filters.state=b.dataset.state;const next=services.find(s=>s.status===filters.state&&(!filters.worker||s.employee_id===filters.worker));if(next){filters.date=local(next.starts_at).slice(0,10);const date=new Date(filters.date+'T12:00:00');calendarMonth=new Date(date.getFullYear(),date.getMonth(),1)}}
 if(action==='new-service'){epoch++;createDraft.request_id||=crypto.randomUUID();createOpen=true;createError='';dirtyForm=true}
 if(action==='close-create'){createOpen=false;dirtyForm=false}
 render();if(createOpen)root.querySelector('#coordCreate input')?.focus();else if(action==='close-create')root.querySelector('[data-action="new-service"]')?.focus();
});
root.addEventListener('input',event=>{if(event.target.form?.id==='coordCreate')createDraft[event.target.name]=event.target.value});
root.addEventListener('change',event=>{const t=event.target;if(t.form?.id!=='coordCreate')return;createDraft[t.name]=t.value;if(t.name==='client_ref'){const c=vault()?.clientes.find(c=>c.id===t.value);if(c){for(const [name,value] of Object.entries({client_name:c.nombre,phone:c.telefono||'',address:typeof addressOf==='function'?addressOf(c):c.direccion||''})){createDraft[name]=value;t.form.elements[name].value=value}}}});
root.addEventListener('submit',async event=>{if(event.target.id!=='coordCreate')return;event.preventDefault();event.stopImmediatePropagation();if(busy)return;busy=true;root.querySelectorAll('button').forEach(b=>b.disabled=true);let saved=false;try{const created=await createService(event.target);saved=true;createOpen=false;createDraft={};createError='';dirtyForm=false;filters.date=created.date;filters.state='active';filters.worker='';calendarMonth=new Date(new Date(created.date+'T12:00:00').getFullYear(),new Date(created.date+'T12:00:00').getMonth(),1);section='agenda';render();const synced=await refresh();if(!synced){status('El servicio se ha creado. Pulsa Actualizar para comprobar la agenda y su copia en Gestión.',true);return}status('Servicio creado y registrado en Cobros de Gestión'+(created.result.status==='offered'?' y enviado para aceptación.':created.result.status==='assigned'?' y asignado al trabajador.':'. Ya puedes asignarlo desde su ficha.'))}catch(err){if(!saved){createError=err.message;const el=q('coordCreateError');if(el){el.textContent=createError;el.hidden=false}dirtyForm=true}else status('Servicio creado en coordinación. '+err.message,true)}finally{busy=false;root.querySelectorAll('button').forEach(b=>b.disabled=false);if(selectedServiceId)root.querySelector('[data-action="close-service"]')?.focus()}});
root.addEventListener('keydown',event=>{if(!createOpen)return;if(event.key==='Escape'){event.preventDefault();createOpen=false;dirtyForm=false;render();root.querySelector('[data-action="new-service"]')?.focus()}if(event.key==='Tab'){const dialog=root.querySelector('.coord-dialog'),all=[...dialog.querySelectorAll('button,input,select,textarea')].filter(el=>!el.disabled),first=all[0],last=all[all.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});

root.addEventListener('submit',async event=>{event.preventDefault();if(busy)return;dirtyForm=false;busy=true;root.querySelectorAll('button').forEach(b=>b.disabled=true);const form=event.target;try{if(form.id==='coordLogin'){await authenticate(form,event.submitter?.name==='signup');return}if(!session)throw new Error('Inicia sesión.');if(form.id==='coordWorker'){const d=new FormData(form),worker=vault()?.empleados?.find(w=>w.id===d.get('employee_id'));if(!worker)throw new Error('Selecciona un empleado de Gestión.');await command('worker',{employee_id:worker.id,name:worker.nombre,email:d.get('email').trim(),active:d.get('active')==='true'})}if(form.id==='coordPublish')await publish(form);if(form.classList.contains('coordSchedule')){const s=services.find(s=>s.id===form.dataset.id),data=Object.fromEntries(new FormData(form));const start=new Date(data.starts_at),end=new Date(data.ends_at),hours=(end-start)/3600000,legacy=vault()?.servicios.find(x=>x.id===s.id);if(!(hours>=.5&&hours<=24&&Number.isInteger(hours*2)))throw new Error('La duración debe ser de 0,5 a 24 horas, en pasos de media hora.');if(legacy?.modo==='bono'&&typeof editablePackHours==='function'&&hours>editablePackHours(legacy))throw new Error('La duración supera el saldo disponible del pack.');if(legacy?.modo==='puntual'&&hours!==Number(legacy.horas)&&!confirm('La duración cambia el importe del servicio en Gestión. ¿Guardar?'))return;await command('publish',{...s,starts_at:start.toISOString(),ends_at:end.toISOString(),instructions:data.instructions})}if(form.id==='coordAvailability'){const data=Object.fromEntries(new FormData(form));data.starts_at=new Date(data.starts_at).toISOString();data.ends_at=new Date(data.ends_at).toISOString();await command('availability',data)}await refresh();status('Cambios guardados y disponibles para el equipo.')}catch(err){status(err.message,true)}finally{busy=false;root.querySelectorAll('button').forEach(b=>b.disabled=false);if(selectedServiceId)root.querySelector('[data-action="close-service"]')?.focus()}});
root.addEventListener('change',async event=>{const t=event.target;if(t.id==='coordCompany'){createDraft={};createOpen=false;dirtyForm=false;company=t.value;epoch++;await refresh();return}if(t.id==='coordDate')filters.date=t.value;if(t.id==='coordState')filters.state=t.value;if(t.id==='coordWorkerFilter')filters.worker=t.value;if(['coordDate','coordState','coordWorkerFilter'].includes(t.id))render();if(t.form?.id==='coordPublish'&&t.name==='id'){const s=vault()?.servicios.find(s=>s.id===t.value),c=vault()?.clientes.find(c=>c.id===s?.cliente),old=services.find(s=>s.id===t.value);t.form.elements.instructions.value=old?.instructions||'';q('coordPreview').textContent=s&&c?c.nombre+' · '+(c.telefono||'Sin teléfono')+' · '+(s.direccion||addressOf(c))+' · '+s.fecha+' '+s.hora+' · '+s.horas+' h':''}});
root.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b||busy)return;const action=b.dataset.action;if(action==='close'){if(admin)openManagement();return}if(action==='all-dates'){filters.date='';render();return}busy=true;root.querySelectorAll('button').forEach(b=>b.disabled=true);try{if(action==='logout'){selectedServiceId='';drawerDirty=false;serviceQuery='';listDate='';joinRequests=[];signupMode=false;const old=session;if(vault())await originalLogout();workspace='home';personalFilters={date:'',state:'active'};epoch++;session=null;company=null;admin=false;workers=[];services=[];blocks=[];events=[];members=[];lastAt='';createOpen=false;createDraft={};createError='';section='resumen';dirtyForm=false;filters={date:day(),state:'active',worker:''};login();if(old)await raw('/auth/v1/logout',{},old.access_token).catch(()=>{});return}if(action==='refresh'){if(createOpen){status('Guarda o cierra el formulario antes de actualizar.');return}await refresh();return}if(action==='import-blocks'){const message=await importBlocks();await refresh();status(message);return}if(action==='unblock'){const block=blocks.find(x=>x.id===b.dataset.id);await command('remove_availability',{id:block.id,employee_id:block.employee_id})}else{const s=services.find(s=>s.id===b.dataset.id);if(!s)throw new Error('Actualiza la lista de servicios.');const payload={id:s.id,version:s.version};if(action==='assign'){payload.employee_id=[...root.querySelectorAll('[data-worker]')].find(el=>el.dataset.worker===s.id).value;payload.mode=[...root.querySelectorAll('[data-mode]')].find(el=>el.dataset.mode===s.id).value;const conflict=legacyConflict(payload.employee_id,s);if(conflict)throw new Error(conflict);if(vault())await importBlocks()}if(action==='incident'||action==='reject'){const detail=prompt(action==='incident'?'Describe la incidencia:':'Motivo del rechazo (opcional):');if(detail===null)return;payload.detail=detail;if(action==='incident'&&!detail.trim())throw new Error('Describe la incidencia.')}if(['cancel','complete'].includes(action)&&!confirm(action==='cancel'?'¿Cancelar este servicio? Se conservará en el historial.':'¿Confirmas que has terminado este servicio?'))return;await command(action,payload)}await refresh();status('Cambio guardado.')}catch(err){status(err.message,true);if(/cambiado|versión/.test(err.message)){await refresh();status(err.message,true)}}finally{busy=false;root.querySelectorAll('button').forEach(b=>b.disabled=false);if(selectedServiceId)root.querySelector('[data-action="close-service"]')?.focus()}});
function open(){signupMode=false;dirtyForm=false;root.hidden=false;if(session){workspace=admin?(desktop()?'home':'personal'):'personal';render();refresh()}else login();root.querySelector('input,button')?.focus()}
window.umecOpenCoordination=()=>{dirtyForm=false;root.hidden=false;workspace=admin&&desktop()?'coordination':'personal';if(session){render();refresh()}else login()};
const originalAssignmentPanel=employeeAssignmentPanel;
employeeAssignmentPanel=function(s){if(!s.coord)return originalAssignmentPanel(s);return '<div class="notice">Coordinación: '+e(labels[s.coord.status]||s.coord.status)+'<p>El horario y la asignación se gestionan desde el Centro de Coordinación.</p><button class="btn" type="button" onclick="umecOpenCoordination()">Abrir coordinación</button></div>'};
const originalServiceCard=serviceCard;
serviceCard=function(s,pending){let html=originalServiceCard(s,pending);if(s.coord)html=html.replace('</div>','<span class="tag">Coordinación: '+e(labels[s.coord.status]||s.coord.status)+'</span></div>');return html};
const originalSaveServiceEdit=saveServiceEdit;
saveServiceEdit=async function(){if(editorService()?.coord){open();return}return originalSaveServiceEdit()};
const originalCancel=cancelService;
cancelService=async function(id){const s=vault()?.servicios.find(s=>s.id===id);if(!s?.coord)return originalCancel(id);if(!session||!admin||company!==s.coord.company){open();return}if(!confirm('¿Cancelar el servicio en coordinación y Gestión?'))return;try{const remote=services.find(s=>s.id===id);if(!remote)throw new Error('Actualiza coordinación primero.');await command('cancel',{id,version:remote.version});await refresh();}catch(err){alert(err.message)}};
const originalClose=closeService;
closeService=function(id){const s=vault()?.servicios.find(s=>s.id===id);if(s?.coord&&s.coord.status!=='completed'){alert('El trabajador debe finalizar el servicio en coordinación antes de cerrar sus cobros.');open();return}return originalClose(id)};
const originalLogout=logout;
logout=async function(){selectedServiceId='';drawerDirty=false;serviceQuery='';listDate='';joinRequests=[];signupMode=false;const old=session;createOpen=false;createDraft={};createError='';section='resumen';workspace='home';personalFilters={date:'',state:'active'};epoch++;session=null;company=null;admin=false;workers=[];services=[];blocks=[];events=[];members=[];await originalLogout();root.hidden=false;login();if(old)await raw('/auth/v1/logout',{},old.access_token).catch(()=>{})};
