const bookingConflictBeforePlanning=serviceBookingConflict;
serviceBookingConflict=function(owner,service,excludeId){const previous=bookingConflictBeforePlanning(owner,service,excludeId);if(previous||!session||!company||!owner)return previous;const range=serviceTimeRange(service);if(!range)return 'Indica un horario válido.';if(blocks.some(b=>b.employee_id===owner&&new Date(b.starts_at)<range.end&&range.start<new Date(b.ends_at)))return 'El trabajador tiene un bloqueo compartido en ese horario.';if(services.some(s=>s.employee_id===owner&&s.id!==excludeId&&['offered','assigned','in_progress','incident'].includes(s.status)&&new Date(s.starts_at)<range.end&&range.start<new Date(s.ends_at)))return 'El trabajador ya tiene un servicio en Coordinación en ese horario.';return ''};
const employeeBlockedBeforePlanning=employeeBlocked;
employeeBlocked=function(owner,date){if(employeeBlockedBeforePlanning(owner,date))return true;const start=new Date(date+'T00:00:00'),end=new Date(start);end.setDate(end.getDate()+1);return !!session&&blocks.some(b=>b.employee_id===owner&&new Date(b.starts_at)<=start&&new Date(b.ends_at)>=end)};

